INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1072942-phys301', 'stk-metallic', 'PHYS 301', 'info', '{"desc": "UP\n\nTopics covered include: Newton’s laws of motion and conservation theorems, oscillations; non-linear oscillations and chaos; Computational study of forced oscillatory motion and nonlinear motion gravitation; Hamilton’s variational principle – Lagrangian and Hamiltonian Dynamics; Central force; Motion in a non-inertial reference frame.\n\nأنا سبق وقريت معلومات الكورس الموجودة في موقع ديبارتمنت الفيزيكس … بس محتاج آرائكم فيه وتبيين مدى صعوبته … 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-301-classical-mechanics-i/120510/2", "user": "METALLIC", "ts": 1343447766000, "tid": 120510, "pn": 2}}', 1343447766000, 1794774616, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1420434-phys301', 'stk-jarir', 'PHYS 301', 'info', '{"desc": "جودة المقرر بشكل عام\n\nجيد جدا\nالمقرر أساسي و مهم جدا . وهو مدخل للفيزياء الكمية (Quantum Physics) وبقية العلوم الفيزيائية.\n\nالمواضيع التي يغطيها المقرر\n\nيتطرق المقرر للحركة بشكل عام\nالفصل 2 : يتكلم عن قوانين نيوتن و معادلات الحركة لل(Particles) , نظريات حفظ الطاقة وحفظ كمية الحركة .\n\nالفصل 3 : الحركة التوافقية (harmonic oscillations) و ال(phase diagram) و العلاقة بين النظام الميكانيكي والنظام الكهربائي.\n\nالفصل 4 : العشوائية (chaos).\n\nالفصل 5 : الجاذبية (Gravitation) و (Gauss law).\n\nالفصل 6 : Calculus of Variations >>>>>>> رياضيات.\n\nالفصل 7 : (هذا أهم شي بالمقرر) … يتكلم عن (Euler-Lagrange equation) و قوانين هاميلتون للحركة.\n\nالفصل 8 : Central Force Motion و قوانين كيبلر\n\nالفصل الأخير: Motion of center of mass\n\nالكتاب المستخدم للمقرر\n\nThornton S. T. and Marion, J. B.: Classical Dynamics of Particles and Systems, 5th edition, Saunders College Publishing, 2004\nالكتاب جيد جدا ويحتوي على أمثلة كثيرة ومتنوعة بالإضافة لتمارين كثيرة وصعبة نهاية كل فصل.\n\nملاحظات\n-المقرر يتطلب إستخدام برنامج (Mathmatica) للفصل الخامس (Chaos).\n-يالمقرر يعتمد على الراضيات بشكل كبير. يفضل إنك تكون مخلص math 301.\n-المقرر أسهل بكثير من physics 101 لكنه عميق جدا.\n-من المهم أن تنتبه جيدا لشرح الدكتور لأن المقرر بداية وأساس لكثير من العلوم الفيزيائية.\n-على الطالب أن يجيد قراءة وفهم ال (diagrams).\n-المقرر ممتع خصوصا في الفصل السابع.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-301-classical-mechanics-i/120510/4", "user": "jarir", "ts": 1421624219000, "tid": 120510, "pn": 4}}', 1421624219000, 1794774616, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1463715-phys301', 'stk-najiali', 'PHYS 301', 'info', '{"desc": "301 كورس يعتمد على الماث بشكل كبير جدا. اغلب الامور فيه تتعلق بإيجاد معادلة تصف حركة جسم معين.\n\nيتطرق الكورس لحل بعض المسائل بطرق مختلفة تعطي نفس النتيجة لو استخدمنا الطرق التقليدية في الحل. مثلا حركة جسم على سطح كرة وتسارع الجسم وغيرها من الممكن إيجاد معادلة عن طريق الفيكتور للحركة لكن الحل راح يكون معقد جدا. لهذا الكتاب يستخدم طرق اخرى لإيجاد الحل وهي بستخدام قوانين هاميلتون و لاغرانج.\n\nأعتقد لو كنت ممتاز في الماث ماراح تواجه صعوبة لان اغلب الامور الموجودة بتكون مارة عليك من قبل لكن طريقة الحل مختلفة ماعدا الشيء البسيط من المقرر اللي راح يكون جديد نسبيا. الدكتور اللي يدرس الكورس لازم يستخدم التفصيل في حل المسألة ولا راح تضيع في بعض الامور بذات الاشياء القديمة اللي دارسها في ماث 002. بالعموم كورس ممتع لو نظرت له بعين ال mathematicians", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-301-classical-mechanics-i/120510/5", "user": "NajiAli", "ts": 1480885665000, "tid": 120510, "pn": 5}}', 1480885665000, 1794774616, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
